package com.personal.meditation;
import static org.junit.Assert.*;import android.content.*;import android.os.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ServiceController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28)public class MeditationServiceTest{
 @Before public void reset(){MeditationService.busy=false;MeditationService.snapshot="{\"phase\":\"idle\"}";RuntimeEnvironment.getApplication().getSharedPreferences("meditation_settings",0).edit().clear().commit();}
 @Test public void foregroundTimerCanPauseResumeAndStopWithoutTheActivity()throws Exception{ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService s=controller.get();try{s.onStartCommand(new Intent().setAction(MeditationService.START),0,1);assertTrue(MeditationService.busy);assertEquals("preparing",new JSONObject(MeditationService.snapshot).getString("phase"));assertNotNull(Shadows.shadowOf(s).getLastForegroundNotification());s.onStartCommand(new Intent().setAction(MeditationService.PAUSE),0,2);assertEquals("paused",new JSONObject(MeditationService.snapshot).getString("phase"));s.onStartCommand(new Intent().setAction(MeditationService.RESUME),0,3);assertEquals("preparing",new JSONObject(MeditationService.snapshot).getString("phase"));s.onStartCommand(new Intent().setAction(MeditationService.STOP),0,4);assertFalse(MeditationService.busy);assertEquals("idle",new JSONObject(MeditationService.snapshot).getString("phase"));}finally{controller.destroy();}}
 @Test public void timeDisplayRoundsUp(){assertEquals("00:30",MeditationService.time(30000));assertEquals("00:30",MeditationService.time(29001));assertEquals("02:30",MeditationService.time(150000));assertEquals("00:00",MeditationService.time(0));}
 @Test public void liveStateReadsBetweenPublishedTicksWithoutQuantizingTheClock()throws Exception{ServiceController<MeditationService> controller=Robolectric.buildService(MeditationService.class).create();MeditationService service=controller.get();try{long start=SystemClock.elapsedRealtime();service.onStartCommand(new Intent().setAction(MeditationService.START),0,1);Shadows.shadowOf(Looper.getMainLooper()).idleFor(1375,java.util.concurrent.TimeUnit.MILLISECONDS);long expected=30000-(SystemClock.elapsedRealtime()-start),live=new JSONObject(MeditationService.liveState()).getLong("remainingMs"),cached=new JSONObject(MeditationService.snapshot).getLong("remainingMs");assertEquals(expected,live);assertTrue(live<cached);service.onStartCommand(new Intent().setAction(MeditationService.PAUSE),0,2);long paused=new JSONObject(MeditationService.liveState()).getLong("remainingMs");Shadows.shadowOf(Looper.getMainLooper()).idleFor(2500,java.util.concurrent.TimeUnit.MILLISECONDS);assertEquals(paused,new JSONObject(MeditationService.liveState()).getLong("remainingMs"));service.onStartCommand(new Intent().setAction(MeditationService.STOP),0,3);}finally{controller.destroy();}}
}
